      pt: ["Área de estufas: 40.000 ha", "Produção anual de vegetais: Milhões de toneladas", "Empregados: >500.000", "Turistas anuais: >2 milhões", "Tamanho do Mercado Internacional de Vegetais: 200 ha", "Principais produtos: pepinos, tomates, pimentos"],
