      ro: ["Recunoscută ca Rezervație a Biosferei UNESCO în 1979", "Habitat natural pentru rarisimul tigru siberian", "Prezența a peste 200 de specii diferite de păsări", "Variații de altitudine de la 500 la peste 2.600 metri", "Zonă protejată pentru leopardul de Amur periclitat", "Lacul Tianchi este situat la 2.189 metri altitudine"],
      en: ["Recognized as a UNESCO Biosphere Reserve in 1979", "Natural habitat for the rare Siberian tiger", "Home to over 200 different bird species", "Elevation ranges from 500 to over 2,600 meters", "Protected area for the endangered Amur leopard", "The central Heaven Lake sits at 2,189 meters altitude"],
      es: ["Pico más alto: Monte Baekdu (2.744 m)", "Lago Tianchi: 2.189 m sobre el nivel del mar", "Parque Nacional fundado: 1960", "Superficie: 2.000 km²", "Precipitación anual: 1.400 mm", "Temperatura media en enero: -18°C"],
      pt: ["Pico mais alto: Monte Baekdu (2.744 m)", "Lago Tianchi: 2.189 m acima do nível do mar", "Parque Nacional fundado: 1960", "Área: 2.000 km²", "Precipitação anual: 1.400 mm", "Temperatura média em janeiro: -18°C"],
      fr: ["Sommet le plus élevé : Mont Baekdu (2 744 m)", "Lac Tianchi : 2 189 m au-dessus du niveau de la mer", "Date de création du parc national : 1960", "Superficie : 2 000 km²", "Précipitations annuelles : 1 400 mm", "Température moyenne en janvier : -18°C"],
