    descriptionAdvanced: {
      de: "Der Dounan-Blumenmarkt in Kunming, der Hauptstadt der Provinz Yunnan, ist der größte Frischblumenmarkt in Asien und ein zentraler Knotenpunkt im globalen Blumenhandel. Er wurde Ende der 1980er Jahre als kleiner Straßenmarkt gegründet und hat sich zu einem gigantischen Handelszentrum entwickelt, das täglich über 20 Millionen Stiele umschlägt. Mehr als 80 Prozent der in China verkauften Frischblumen stammen von hier oder werden über dieses Zentrum gehandelt. Der Markt arbeitet rund um die Uhr, wobei die Auktionen im Kunming International Flora Auction Trading Center (KIFA) zu den wichtigsten Ereignissen gehören. Yunnan bietet aufgrund seiner klimatischen Bedingungen das ganze Jahr über ideale Voraussetzungen für den Anbau von Rosen, Lilien und Nelken. Die Blumen von Dounan werden in über 40 Länder exportiert, was den Markt zu einem wirtschaftlichen Motor der Region macht. Besucher können hier die beeindruckende Logistik und die unglaubliche Vielfalt von über 1.600 Blumensorten hautnah erleben.",
      hu: "A Kunmingben található Dounan virágpiac Ázsia legnagyobb vágottvirág-piaca, és a globális virágkereskedelem egyik legfontosabb csomópontja. Az 1980-as évek végén még apró utcai piacként indult, mára azonban egy hatalmas kereskedelmi komplexummá nőtte ki magát, ahol naponta több mint 20 millió szál virág cserél gazdát. Kína friss vágott virágainak több mint 80 százaléka innen származik vagy ezen a központon keresztül kerül forgalomba. A piac napi 24 órában üzemel, a legjelentősebb tranzakciók pedig a Kunming Nemzetközi Virágárverési Központban (KIFA) zajlanak. Jünnan tartomány kedvező éghajlati adottságai lehetővé teszik a rózsák, liliomok és szegfűk egész éves termesztését és értékesítését. A Dounanból származó virágokat több mint 40 országba exportálják, ami meghatározó gazdasági tényező a régió számára. A látogatók számára lenyűgöző élményt nyújt a logisztikai gépezet és a több mint 1600 elérhető virágfajta látványa.",
      ro: "Piața de flori Dounan din Kunming, capitala provinciei Yunnan, este cea mai mare piață de flori tăiate din Asia și un punct cheie în comerțul global cu plante. Înființată la sfârșitul anilor 1980 ca o mică piață stradală, aceasta s-a transformat într-un centru comercial gigantic care gestionează zilnic peste 20 de milioane de tulpini de flori. Peste 80% din florile proaspete vândute în China provin sau sunt tranzacționate prin acest centru de distribuție. Piața funcționează non-stop, iar licitațiile desfășurate la Centrul Internațional de Licitații de Flori din Kunming (KIFA) sunt printre cele mai importante din lume. Datorită climatului favorabil din Yunnan, aici se cultivă pe tot parcursul anului trandafiri, crini și garoafe de o calitate superioară. Florile de la Dounan sunt exportate în peste 40 de țări, reprezentând un motor economic vital pentru întreaga regiune. Vizitatorii pot asista aici la un proces logistic impresionant și pot explora o varietate de peste 1.600 de specii de flori.",
      en: "The Dounan Flower Market in Kunming, the capital of Yunnan Province, is the largest fresh-cut flower market in Asia and a vital hub in the global floral trade. Established in the late 1980s as a modest street market, it has evolved into a massive trading complex that handles over 20 million stems of flowers daily. More than 80% of the fresh flowers sold in China either originate from here or pass through this central distribution point. The market operates 24 hours a day, with high-stakes auctions at the Kunming International Flora Auction Trading Center (KIFA) serving as a highlight of the trade cycle. Yunnan's favorable climate allows for the year-round cultivation of roses, lilies, and carnations, ensuring a steady supply. Flowers from Dounan are exported to over 40 countries, making the market a significant economic engine for the region. Visitors can witness a sophisticated logistical operation and an incredible diversity of over 1,600 flower varieties on display.",
      es: "El Mercado de Flores de Dounan en Kunming, China, es el más grande de Asia. Inaugurado en 1999, abarca más de 100.000 m². Cada día se comercializan más de 10 millones de flores cortadas. El mercado ofrece unas 2.000 especies, incluyendo rosas, lirios y orquídeas. Está abierto las 24 horas del día. Alcanza una facturación anual de más de 10.000 millones de yuanes y exporta a más de 50 países. El promedio de visitantes diarios es de 30.000 personas.",
      pt: "O Mercado de Flores de Dounan em Kunming, na China, é o maior mercado de flores da Ásia. Foi inaugurado em 1999 e estende-se por 100.000 m². Diariamente, são comercializadas aqui mais de 10 milhões de flores de corte. O mercado oferece cerca de 2.000 tipos de flores, incluindo rosas, lírios e orquídeas. O mercado está aberto 24 horas por dia. Anualmente, é alcançado um volume de negócios de mais de 10 mil milhões de yuan. O mercado exporta para mais de 50 países. O número médio de visitantes diários é de 30.000.",
      fr: "Le marché aux fleurs de Dounan à Kunming, en Chine, est le plus grand d'Asie. Ouvert en 1999, il s'étend sur plus de 100 000 m². Plus de 10 millions de fleurs coupées y sont vendues chaque jour. Le marché propose environ 2 000 variétés de fleurs, dont des roses, des lys et des orchidées. Il est ouvert 24h/24. Son chiffre d'affaires annuel dépasse les 10 milliards de yuans. Il exporte vers plus de 50 pays. Le nombre moyen de visiteurs quotidiens est de 30 000.",
    },
